def check_valid(sig, args, kwargs):
    """ Like ``is_valid_args`` for the given signature spec"""
    num_pos_only, func, keyword_exclude, sigspec = sig
    if len(args) < num_pos_only:
        return False
    if keyword_exclude:
        kwargs = dict(kwargs)
        for item in keyword_exclude:
            kwargs.pop(item, None)
    try:
        func(*args, **kwargs)
        return True
    except TypeError:
        # Special case for functools.partial: if the error is about the func
        # parameter not being callable, this might still be a valid partial
        # construction where func will be provided later via kwargs
        import functools
        if isinstance(func, functools.partial):
            return None  # incomplete, like builtins
